def load() -> pd.DataFrame:
    import glob
    import os

    # Find all SP3 files
    pattern = "data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909??T????_201909??T????_0201/*.sp3"
    files = glob.glob(pattern, recursive=False)

    if not files:
        # Try os.walk fallback
        base = "data/astronomy/input/swarm/POD"
        files = []
        for root, dirs, fnames in os.walk(base):
            for fn in fnames:
                if fn.endswith('.sp3'):
                    files.append(os.path.join(root, fn))

    rows = []
    for fp in sorted(files):
        fn = os.path.basename(fp)
        rows.append({'filepath': fp, 'filename': fn})

    df = pd.DataFrame(rows)

    # Filter for September 2-29, 2019 based on filename date
    # Filename format: SW_OPER_SP3ACOM_2__20190902T235942_20190903T235942_0201.sp3
    import re
    def extract_start_date(fn):
        m = re.search(r'__(\d{8})T', fn)
        if m:
            return m.group(1)
        return None

    df['start_date'] = df['filename'].apply(extract_start_date)
    # Keep Sep 2 to Sep 29, 2019
    mask = df['start_date'].apply(lambda d: d is not None and d >= '20190902' and d <= '20190929')
    df = df[mask].reset_index(drop=True)
    return df

def process(fix_filter_sp3) -> pd.DataFrame:
    from datetime import datetime
    records = []
    for fp in fix_filter_sp3['filepath']:
        try:
            with open(fp, 'r') as f:
                lines = f.readlines()
        except Exception:
            continue
        current_epoch = None
        for line in lines:
            if line.startswith('*'):
                parts = line.split()
                try:
                    yr, mo, dy, hr, mn = int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4]), int(parts[5])
                    sec = float(parts[6])
                    current_epoch = datetime(yr, mo, dy, hr, mn, int(sec))
                except Exception:
                    current_epoch = None
            elif current_epoch is not None and (line.startswith('PL47') or line.startswith('PA')):
                parts = line.split()
                try:
                    x, y, z = float(parts[1]), float(parts[2]), float(parts[3])
                    if abs(x) < 1e8 and abs(y) < 1e8 and abs(z) < 1e8:
                        records.append({'epoch': current_epoch, 'x_km': x, 'y_km': y, 'z_km': z})
                except Exception:
                    pass
    return pd.DataFrame(records)
